<script setup lang="ts">import {ref,computed,onMounted,onUnmounted} from 'vue';const props=defineProps<{modelValue:number[];options:any[];labelKey:string;placeholder?:string;searchPlaceholder?:string;emptyText?:string;roleLabels?:boolean}>();const emit=defineEmits(['update:modelValue']);const root=ref<HTMLElement|null>(null),opened=ref(false),search=ref('');const matches=computed(()=>props.options.filter(o=>(String(o[props.labelKey])+' '+(props.roleLabels?o.roles?.map((r:any)=>r.role_name).join(' '):'')).toLowerCase().includes(search.value.toLowerCase())));function toggle(id:number){emit('update:modelValue',props.modelValue.includes(id)?props.modelValue.filter(i=>i!==id):[...props.modelValue,id]);}function outside(e:Event){if(!root.value?.contains(e.target as Node))opened.value=false;}onMounted(()=>document.addEventListener('pointerdown',outside));onUnmounted(()=>document.removeEventListener('pointerdown',outside));</script><template><div ref="root" class="pms-multiselect"><button type="button" class="pms-multiselect-trigger" :aria-expanded="opened" @click="opened=!opened"><span v-if="!modelValue.length" class="muted">{{placeholder||'Search and select'}}</span><span v-for="id in modelValue" :key="id" class="pms-multiselect-tag">{{options.find(o=>o.id===id)?.[labelKey]}}</span><i aria-hidden="true" class="ti ti-chevron-down"></i></button><div v-if="opened" class="pms-multiselect-menu" @keydown.esc.stop="opened=false"><input v-model="search" :aria-label="searchPlaceholder||'Search options'" :placeholder="searchPlaceholder||'Search...'"><div class="pms-multiselect-options"><label v-for="option in matches" :key="option.id" class="check"><input type="checkbox" :checked="modelValue.includes(option.id)" @change="toggle(option.id)"><span>{{option[labelKey]}}</span><small v-if="roleLabels" class="pms-employee-role">{{option.roles?.map((r:any)=>r.role_name).join(', ')||'Employee'}}</small></label><p v-if="!matches.length" class="muted">{{emptyText||'No options found.'}}</p></div></div></div></template>